        "context": "住戶回饋有輪椅的轉彎，也有一句簡單的不好走。傾城看過頁首，就把整疊推開，拿起知名機構的信。她認為只有特定名校與機構的人懂自己，一般使用者的問題已幾次被擱下。你把坡道那張翻回來。這不是排名，是真的有人走不過去。",
